#!/usr/bin/env python3
import pathlib, subprocess, os
ROOT=pathlib.Path("/home/apr/eth-hedge-live")
BOT=ROOT/"shadow_exec_bot.py"
BOT.write_text("#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, fcntl, json, os, pathlib, time, urllib.parse, urllib.request\nfrom datetime import datetime, timezone\n\nROOT=pathlib.Path(\"/home/apr/eth-hedge-live\")\nMONITOR_STATE=ROOT/\"state.json\"\nMONITOR_CONFIG=ROOT/\"config.json\"\nSTATE=ROOT/\"shadow_exec_state.json\"\nLEDGER=ROOT/\"shadow_exec_ledger.jsonl\"\nLOCK=ROOT/\"shadow_exec.lock\"\nBINANCE=\"https://fapi.binance.com/fapi/v1/klines\"\n\nQTY_ETH=0.1\nTP_PCT=0.003\nADVERSE_PCT=0.015\nROUND_TRIP_COST_PCT=0.001\n\ndef now_ms(): return int(time.time()*1000)\ndef iso(ms=None):\n    if ms is None: return datetime.now(timezone.utc).isoformat()\n    return datetime.fromtimestamp(ms/1000,tz=timezone.utc).isoformat()\n\ndef load_json(p,default=None):\n    if not p.exists(): return default\n    return json.loads(p.read_text())\n\ndef save_json(p,obj):\n    tmp=p.with_suffix(p.suffix+\".tmp\")\n    tmp.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+\"\\n\",encoding=\"utf-8\")\n    os.replace(tmp,p)\n    os.chmod(p,0o600)\n\ndef emit(event,**kw):\n    row={\"event\":event,\"at\":iso(),**kw}\n    with LEDGER.open(\"a\",encoding=\"utf-8\") as f:\n        f.write(json.dumps(row,ensure_ascii=False,separators=(\",\",\":\"))+\"\\n\")\n\ndef fetch_bars(limit=500):\n    qs=urllib.parse.urlencode({\"symbol\":\"ETHUSDT\",\"interval\":\"5m\",\"limit\":limit})\n    req=urllib.request.Request(BINANCE+\"?\"+qs,headers={\"User-Agent\":\"eth-hedge-shadow-exec/1.0\"})\n    with urllib.request.urlopen(req,timeout=20) as r:\n        raw=json.load(r)\n    cutoff=now_ms()-1000\n    out=[]\n    for x in raw:\n        b={\n            \"open_ts\":int(x[0]),\"open\":float(x[1]),\"high\":float(x[2]),\"low\":float(x[3]),\n            \"close\":float(x[4]),\"close_ts\":int(x[6])\n        }\n        if b[\"close_ts\"]<cutoff:\n            out.append(b)\n    return out\n\ndef new_state():\n    return {\n        \"version\":1,\n        \"mode\":\"SHADOW_NO_ORDERS\",\n        \"last_seen_signal_close_ts\":0,\n        \"last_processed_close_ts\":0,\n        \"shadow_start_ts\":now_ms(),\n        \"last_completed_signal_close_ts\":0,\n        \"pending\":None,\n        \"position\":None,\n        \"stats\":{\n            \"signals_seen\":0,\n            \"entries\":0,\n            \"tp_exits\":0,\n            \"completed_trades\":0,\n            \"gross_pnl_usd\":0.0,\n            \"estimated_cost_usd\":0.0,\n            \"net_pnl_usd\":0.0,\n            \"adverse_1_5_touches\":0,\n            \"held_over_60m\":0,\n            \"max_mae_pct\":0.0,\n            \"max_hold_minutes\":0\n        }\n    }\n\ndef load_state():\n    s=load_json(STATE)\n    return s if isinstance(s,dict) else new_state()\n\ndef current_unrealized(p,mark):\n    if not p: return 0.0\n    return (float(p[\"entry_price\"])-float(mark))*QTY_ETH\n\ndef close_tp(s,b):\n    p=s[\"position\"]\n    exit_px=float(p[\"tp_price\"])\n    gross=(float(p[\"entry_price\"])-exit_px)*QTY_ETH\n    cost=(float(p[\"entry_price\"])*QTY_ETH)*ROUND_TRIP_COST_PCT\n    net=gross-cost\n    rec={\n        \"signal_close_ts\":p[\"signal_close_ts\"],\n        \"entry_ts\":p[\"entry_ts\"],\n        \"exit_ts\":b[\"close_ts\"],\n        \"entry_price\":p[\"entry_price\"],\n        \"exit_price\":exit_px,\n        \"qty_eth\":QTY_ETH,\n        \"bars_held\":p[\"bars_held\"],\n        \"minutes_held\":p[\"bars_held\"]*5,\n        \"mae_pct\":p[\"mae_pct\"],\n        \"mfe_pct\":p[\"mfe_pct\"],\n        \"adverse_1_5_touched\":p[\"adverse_1_5_touched\"],\n        \"held_over_60m\":p[\"held_over_60m\"],\n        \"gross_pnl_usd\":gross,\n        \"estimated_cost_usd\":cost,\n        \"net_pnl_usd\":net\n    }\n    emit(\"SHADOW_TP_EXIT\",**rec)\n    st=s[\"stats\"]\n    st[\"tp_exits\"]+=1\n    st[\"completed_trades\"]+=1\n    st[\"gross_pnl_usd\"]+=gross\n    st[\"estimated_cost_usd\"]+=cost\n    st[\"net_pnl_usd\"]+=net\n    st[\"max_mae_pct\"]=max(float(st.get(\"max_mae_pct\") or 0),float(p[\"mae_pct\"]))\n    st[\"max_hold_minutes\"]=max(int(st.get(\"max_hold_minutes\") or 0),int(p[\"bars_held\"]*5))\n    s[\"last_completed_signal_close_ts\"]=max(int(s.get(\"last_completed_signal_close_ts\") or 0),int(p[\"signal_close_ts\"]))\n    s[\"position\"]=None\n\ndef process():\n    with LOCK.open(\"a+\") as lf:\n        fcntl.flock(lf,fcntl.LOCK_EX)\n        mon=load_json(MONITOR_STATE,{}) or {}\n        cfg=load_json(MONITOR_CONFIG,{}) or {}\n        if int(cfg.get(\"account_index\") or 0)!=749122 or int(cfg.get(\"api_key_index\") or -1)!=45:\n            raise RuntimeError(\"monitor identity mismatch\")\n        if cfg.get(\"mode\")!=\"LOCKED_NO_ORDERS\":\n            raise RuntimeError(\"monitor must remain LOCKED_NO_ORDERS\")\n        s=load_state()\n        bars=fetch_bars()\n        if len(bars)<5: raise RuntimeError(\"not enough bars\")\n        if int(s.get(\"last_processed_close_ts\") or 0)==0:\n            s[\"last_processed_close_ts\"]=int(bars[-1][\"close_ts\"])\n            s.setdefault(\"shadow_start_ts\",now_ms())\n            save_json(STATE,s)\n            print(json.dumps({\"ok\":True,\"initialized\":True,\"mode\":\"SHADOW_NO_ORDERS\"},ensure_ascii=False))\n            return\n\n        # Import each monitor signal exactly once.\n        sig=mon.get(\"active_signal\")\n        if isinstance(sig,dict):\n            sig_ts=int(sig.get(\"signal_close_ts\") or 0)\n            if sig_ts>int(s.get(\"last_seen_signal_close_ts\") or 0):\n                s[\"last_seen_signal_close_ts\"]=sig_ts\n                if sig_ts<int(s.get(\"shadow_start_ts\") or 0):\n                    emit(\"SHADOW_SIGNAL_IGNORED_PRESTART\",signal_close_ts=sig_ts,shadow_start_ts=s.get(\"shadow_start_ts\"))\n                else:\n                    s[\"stats\"][\"signals_seen\"]+=1\n                if sig_ts>=int(s.get(\"shadow_start_ts\") or 0) and s.get(\"position\") is None and s.get(\"pending\") is None and sig_ts>int(s.get(\"last_completed_signal_close_ts\") or 0):\n                    s[\"pending\"]={\n                        \"signal_close_ts\":sig_ts,\n                        \"signal_open_ts\":int(sig.get(\"signal_open_ts\") or 0),\n                        \"rise\":float(sig.get(\"rise\") or 0),\n                        \"buy_share\":float(sig.get(\"buy_share\") or 0),\n                        \"entry_reference\":float(sig.get(\"entry_reference\") or 0),\n                        \"detected_at_ms\":now_ms()\n                    }\n                    emit(\"SHADOW_SIGNAL_ACCEPTED\",**s[\"pending\"])\n                else:\n                    emit(\"SHADOW_SIGNAL_SKIPPED_BUSY_OR_OLD\",signal_close_ts=sig_ts)\n\n        # Process each closed bar exactly once.\n        new_bars=[b for b in bars if int(b[\"close_ts\"])>int(s.get(\"last_processed_close_ts\") or 0)]\n        for b in new_bars:\n            if s.get(\"pending\") and s.get(\"position\") is None:\n                p=s[\"pending\"]\n                if b[\"open_ts\"]>int(p[\"signal_close_ts\"]):\n                    entry=float(b[\"open\"])\n                    s[\"position\"]={\n                        \"signal_close_ts\":int(p[\"signal_close_ts\"]),\n                        \"entry_ts\":int(b[\"open_ts\"]),\n                        \"entry_price\":entry,\n                        \"tp_price\":entry*(1-TP_PCT),\n                        \"adverse_price\":entry*(1+ADVERSE_PCT),\n                        \"bars_held\":0,\n                        \"mae_pct\":0.0,\n                        \"mfe_pct\":0.0,\n                        \"adverse_1_5_touched\":False,\n                        \"held_over_60m\":False,\n                        \"signal\":p\n                    }\n                    s[\"pending\"]=None\n                    s[\"stats\"][\"entries\"]+=1\n                    emit(\"SHADOW_ENTRY\",signal_close_ts=p[\"signal_close_ts\"],entry_ts=b[\"open_ts\"],entry_price=entry,qty_eth=QTY_ETH,tp_price=entry*(1-TP_PCT),adverse_price=entry*(1+ADVERSE_PCT))\n\n            pos=s.get(\"position\")\n            if not pos:\n                continue\n            if b[\"open_ts\"]<int(pos[\"entry_ts\"]):\n                continue\n            pos[\"bars_held\"]+=1\n            entry=float(pos[\"entry_price\"])\n            pos[\"mae_pct\"]=max(float(pos.get(\"mae_pct\") or 0),float(b[\"high\"])/entry-1)\n            pos[\"mfe_pct\"]=max(float(pos.get(\"mfe_pct\") or 0),1-float(b[\"low\"])/entry)\n\n            if not pos[\"adverse_1_5_touched\"] and float(b[\"high\"])>=float(pos[\"adverse_price\"]):\n                pos[\"adverse_1_5_touched\"]=True\n                s[\"stats\"][\"adverse_1_5_touches\"]+=1\n                emit(\"SHADOW_ADVERSE_1_5_DIAG\",signal_close_ts=pos[\"signal_close_ts\"],observed_ts=b[\"close_ts\"],entry_price=entry,diagnostic_price=pos[\"adverse_price\"],auto_exit=False)\n\n            if not pos[\"held_over_60m\"] and pos[\"bars_held\"]>=12:\n                pos[\"held_over_60m\"]=True\n                s[\"stats\"][\"held_over_60m\"]+=1\n                emit(\"SHADOW_60M_DIAG\",signal_close_ts=pos[\"signal_close_ts\"],observed_ts=b[\"close_ts\"],entry_price=entry,auto_exit=False)\n\n            if float(b[\"low\"])<=float(pos[\"tp_price\"]):\n                close_tp(s,b)\n                continue\n\n            s[\"last_processed_close_ts\"]=int(b[\"close_ts\"])\n\n        if new_bars:\n            s[\"last_processed_close_ts\"]=int(new_bars[-1][\"close_ts\"])\n\n        # Current mark and open PnL snapshot.\n        last=float(bars[-1][\"close\"])\n        pos=s.get(\"position\")\n        s[\"snapshot\"]={\n            \"updated_at\":iso(),\n            \"mark_price\":last,\n            \"position_open\":bool(pos),\n            \"unrealized_gross_usd\":current_unrealized(pos,last),\n            \"minutes_held\":int(pos[\"bars_held\"]*5) if pos else 0,\n            \"entry_price\":float(pos[\"entry_price\"]) if pos else None,\n            \"tp_price\":float(pos[\"tp_price\"]) if pos else None,\n            \"adverse_price\":float(pos[\"adverse_price\"]) if pos else None\n        }\n        save_json(STATE,s)\n        print(json.dumps({\"ok\":True,\"mode\":\"SHADOW_NO_ORDERS\",\"state\":s},ensure_ascii=False))\n\ndef status():\n    s=load_state()\n    print(json.dumps({\"ok\":True,\"mode\":\"SHADOW_NO_ORDERS\",\"state\":s,\"ledger\":str(LEDGER)},ensure_ascii=False,indent=2))\n\nif __name__==\"__main__\":\n    ap=argparse.ArgumentParser();ap.add_argument(\"--status\",action=\"store_true\");a=ap.parse_args()\n    status() if a.status else process()\n",encoding="utf-8")
os.chmod(BOT,0o700)
subprocess.run(["python3","-m","py_compile",str(BOT)],check=True)
subprocess.run(["python3",str(BOT)],cwd=str(ROOT),check=True,timeout=40)
cron="* * * * * cd /home/apr/eth-hedge-live && python3 /home/apr/eth-hedge-live/shadow_exec_bot.py >> /home/apr/eth-hedge-live/shadow_exec_cron.log 2>&1"
r=subprocess.run(["crontab","-l"],text=True,capture_output=True)
